    if abs(heading_error) > math.radians(120.0):
        # Adjust heading with max rotation rate of 0.12 rad/s
        if heading_error > 0:
            heading_correction = min(0.12, heading_error)
        else:
            heading_correction = max(-0.12, heading_error)
